"""squeeze command."""


def run(text, opts):
    keep = int(opts.get("keep", 2))
    out, blanks = [], 0
    for line in text.splitlines():
        line = line.rstrip()
        if not line:
            blanks += 1
            continue
        if out and blanks:
            out.extend([""] * min(blanks, keep))
        blanks = 0
        out.append(line)
    return "".join(l + "\n" for l in out)

