"""bullets command."""
import re


def run(text, opts):
    char = str(opts.get("char", '+'))
    out = []
    for line in text.splitlines():
        m = re.match(r"^(\s*)[*+\u2022-] (.*)$", line)
        out.append(m.group(1) + char + " " + m.group(2) if m else line)
    return "".join(l + "\n" for l in out)

