"""grepctx command."""


def run(text, opts):
    pat = opts.get("pat")
    if not pat:
        raise ValueError("option pat is required")
    pat = str(pat)
    ctx = int(opts.get("ctx", 1))
    lines = text.splitlines()
    hits = [i for i, l in enumerate(lines) if pat in l]
    shown = {}
    for i in hits:
        for j in range(max(0, i - ctx), min(len(lines), i + ctx + 1)):
            shown[j] = shown.get(j, False) or j == i
    out, prev = [], None
    for j in sorted(shown):
        if prev is not None and j != prev + 1:
            out.append("--")
        out.append(("* " if shown[j] else "  ") + lines[j])
        prev = j
    return "".join(l + "\n" for l in out)

solution.toolbench/commands/headtail.py:
"""headtail command."""


def run(text, opts):
    head = int(opts.get("head", 5))
    tail = int(opts.get("tail", 2))
    lines = text.splitlines()
    if len(lines) <= head + tail:
        return "".join(l + "\n" for l in lines)
    omitted = len(lines) - head - tail
    kept = lines[:head] + ["... (%d lines omitted)" % omitted] + (lines[len(lines) - tail:] if tail else [])
    return "".join(l + "\n" for l in kept)

