"""wrapat command."""


def run(text, opts):
    width = int(opts.get("width", 40))
    paras, cur = [], []
    for line in text.splitlines():
        if line.strip():
            cur.extend(line.split())
        elif cur:
            paras.append(cur)
            cur = []
    if cur:
        paras.append(cur)
    blocks = []
    for ws in paras:
        lines, line = [], ""
        for w in ws:
            while len(w) > width:
                if line:
                    lines.append(line)
                    line = ""
                lines.append(w[:width])
                w = w[width:]
            if not line:
                line = w
            elif len(line) + 1 + len(w) <= width:
                line += " " + w
            else:
                lines.append(line)
                line = w
        if line:
            lines.append(line)
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks) + ("\n" if blocks else "")

