"""grepctx command."""


def run(text, opts):
    pat = opts.get("pat")
    if not pat:
        raise ValueError("option pat is required")
    pat = str(pat)
    ctx = int(opts.get("ctx", 1))
    lines = text.splitlines()
    hits = [i for i, l in enumerate(lines) if pat in l]
    shown = {}
    for i in hits:
        for j in range(max(0, i - ctx), min(len(lines), i + ctx + 1)):
            shown[j] = shown.get(j, False) or j == i
    out, prev = [], None
    for j in sorted(shown):
        if prev is not None and j != prev + 1:
            out.append("--")
        out.append(("* " if shown[j] else "  ") + lines[j])
        prev = j
    return "".join(l + "\n" for l in out)

solution.toolbench/commands/sortblocks.py:
"""sortblocks command."""


def run(text, opts):
    blocks, cur = [], []
    for line in text.splitlines():
        if line.strip():
            cur.append(line)
        elif cur:
            blocks.append(cur)
            cur = []
    if cur:
        blocks.append(cur)
    key = (lambda b: b[-1].lower()) if opts.get("icase") else (lambda b: b[-1])
    ordered = sorted(blocks, key=key, reverse=bool(opts.get("reverse")))
    return "\n".join("\n".join(b) + "\n" for b in ordered)

solution.toolbench/commands/squeeze.py:
"""squeeze command."""


def run(text, opts):
    keep = int(opts.get("keep", 2))
    out, blanks = [], 0
    for line in text.splitlines():
        line = line.rstrip()
        if not line:
            blanks += 1
            continue
        if out and blanks:
            out.extend([""] * min(blanks, keep))
        blanks = 0
        out.append(line)
    return "".join(l + "\n" for l in out)

