"""sortblocks command."""


def run(text, opts):
    blocks, cur = [], []
    for line in text.splitlines():
        if line.strip():
            cur.append(line)
        elif cur:
            blocks.append(cur)
            cur = []
    if cur:
        blocks.append(cur)
    key = (lambda b: b[0].lower()) if opts.get("icase") else (lambda b: b[0])
    ordered = sorted(blocks, key=key, reverse=bool(opts.get("reverse")))
    return "\n".join("\n".join(b) + "\n" for b in ordered)

