start.toolbench/commands/dedupe.py:
"""dedupe command."""


def run(text, opts):
    icase = bool(opts.get("icase"))
    count = bool(opts.get("count"))
    groups = []
    for line in text.splitlines():
        key = line.lower() if icase else line
        if groups and groups[-1][0] == key:
            groups[-1][2] += 1
        else:
            groups.append([key, line, 1])
    return "".join((line + (' [%d]' % n if count and n > 1 else "")) + "\n" for _, line, n in groups)

start.toolbench/commands/fieldpick.py:
"""fieldpick command."""


def run(text, opts):
    delim = str(opts.get("delim", ';'))
    picks = [int(p) for p in str(opts.get("cols", "1")).split(",")]
    out = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = line.split(delim)
        row = []
        for p in picks:
            i = p - 1 if p > 0 else len(fields) + p
            row.append(fields[i] if 0 <= i < len(fields) else "")
        out.append(delim.join(row))
    return "".join(l + "\n" for l in out)

start.toolbench/commands/grepctx.py:
"""grepctx command."""


def run(text, opts):
    pat = opts.get("pat")
    if not pat:
        raise ValueError("option pat is required")
    pat = str(pat)
    ctx = int(opts.get("ctx", 1))
    lines = text.splitlines()
    hits = [i for i, l in enumerate(lines) if pat in l]
    shown = {}
    for i in hits:
        for j in range(max(0, i - ctx), min(len(lines), i + ctx + 1)):
            shown[j] = shown.get(j, False) or j == i
    out, prev = [], None
    for j in sorted(shown):
        if prev is not None and j != prev + 1:
            out.append("--")
        out.append(("* " if shown[j] else "  ") + lines[j])
        prev = j
    return "".join(l + "\n" for l in out)

